css`
  @font-face {
    font-family: "PokemonFont";
    src: url(../assets/fonts/Pokemon-Solid.ttf) format("truetype");
    font-weight: normal;
    font-style: normal;
  }

  /* La cabecera ocupa solo su alto (flex: 0 0 auto); listar-pokemon toma el resto con flex: 1. */
  .container {
    cursor: url(assets/poke2.png), auto;
    width: 100vw;
    height: 100vh;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    overflow: hidden;
    padding-bottom: 0.75rem;
    box-sizing: border-box;
  }

  banner-title {
    width: 100%;
    flex: 0 0 auto;
  }

  pokemon-type-filter {
    width: 100%;
    flex: 0 0 auto;
    margin-top: 0.8rem;
  }

  pokemon-type-filter.hidden {
    display: none;
  }

  .top-bar {
    width: 100%;
    flex: 0 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.9rem;
    padding: 0.9rem 0 0.6rem;
  }

  pagination-nav {
    width: 100%;
    position: relative;
  }

  pagination-nav.hidden {
    display: none;
  }

  .empty-favorites {
    color: #fff;
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
    font-size: 1rem;
  }

  .error {
    color: #fff;
    background: rgba(180, 30, 30, 0.85);
    padding: 0.5rem 1rem;
    border-radius: 6px;
  }

  listar-pokemon {
    width: 100%;
    flex: 1 1 auto;
    min-height: 0;
    position: relative;
  }

  navbar-buttons {
    height: 0px;
    position: relative;
  }
`

css`
  :host {
    user-select: none;
    width: 100%;
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: flex-end;
    align-items: center;
  }

  .pokedex-button {
    background: rgba(255, 255, 255, 0.6);
    border: none;
    height: 5rem;
    width: 5rem;
    margin: 0 3rem;
    cursor: pointer;
    border-radius: 50%;
    display: flex;
    align-items: center;
    position: relative;
    transition: 0.5s all ease-in-out;
  }

  .pokedex-button:hover {
    background: rgba(200, 200, 200, 0.8);
    transition: 0.5s all ease-in-out;
  }

  .pokedex-button:hover > .icon {
    transform: scale(1.2);
    transition: 0.5s all ease-in-out;
  }

  .pokedex-button:active > .icon {
    transform: scale(0.8);
    transition: 0.2s all ease-in-out;
  }

  .pokedex-button.disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }

  .icon {
    width: 5.5rem;
    height: 5rem;
    background-size: cover;
    transition: 0.5s all ease-in-out;
  }

  .icon.icon-first {
    position: absolute;
    top: 0;
    left: 0;
    background-image: url("assets/NicePng_pokedex-png_2285786.png");
  }

  .backdrop {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background-color: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(4px);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 9999;
    animation: fadeIn 0.3s ease;
  }

  .modal-content {
    animation: scaleUp 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  }

  @keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  @keyframes scaleUp {
    from { transform: scale(0.5); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
  }
`

